INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, 'built_from',
       'Edition-level link added 2026-11-02: this goal is part of the ' ||
       CASE WHEN o.grade_band = '5/6' THEN 'Lehrplan Mensch-Natur-Technik 2026 (Erprobungsfassung)' ELSE 'Lehrplan Biologie 2026 (Erprobungsfassung)' END || '.'
FROM lpm_data_objects o
JOIN curriculum_repository_records r
  ON r.project_id = (SELECT id FROM projects WHERE slug = 'thuringia-curriculum-repository')
 AND r.source_record_id = CASE WHEN o.grade_band = '5/6' THEN 'DELP-EVENT-thueringen-mnt-gymnasium-2026-erprobungsfassung' ELSE 'DELP-EVENT-thueringen-biologie-gymnasium-2026-erprobungsfassung' END
WHERE o.project_id IN (SELECT id FROM projects WHERE slug IN ('evomentor-thuringia', 'evomentor-thuringia-sandbox'))
  AND o.grade_band IN ('5/6', '7/8', '9', '10') AND o.status = 'accepted'
  AND o.content ->> 'curriculum_version' = '2026-erprobungsfassung'
  AND NOT EXISTS (SELECT 1 FROM curriculum_repository_links l WHERE l.data_object_id = o.id AND l.repository_record_id = r.id AND l.relation_type = 'built_from');

INSERT INTO project_repository_links (project_id, repository_project_id, jurisdiction, note)
SELECT p.id, r.id, 'DE-TH', 'Sandbox copy of EvoMentor Thuringia: built from the same Thuringia Lehrplan documents. Added 2026-11-02.'
FROM projects p, projects r
WHERE p.slug = 'evomentor-thuringia-sandbox' AND r.slug = 'thuringia-curriculum-repository'
  AND NOT EXISTS (SELECT 1 FROM project_repository_links x WHERE x.project_id = p.id AND x.repository_project_id = r.id);

DO $$
DECLARE untagged56 integer; unlinked56 integer; sbx integer; bands boolean;
BEGIN
  SELECT count(*) INTO untagged56 FROM lpm_data_objects o
    WHERE o.project_id IN (SELECT id FROM projects WHERE slug IN ('evomentor-thuringia', 'evomentor-thuringia-sandbox'))
      AND o.grade_band = '5/6' AND o.status = 'accepted' AND NOT (o.content ? 'curriculum_version');
  SELECT count(*) INTO unlinked56 FROM lpm_data_objects o
    WHERE o.project_id IN (SELECT id FROM projects WHERE slug IN ('evomentor-thuringia', 'evomentor-thuringia-sandbox'))
      AND o.grade_band = '5/6' AND o.status = 'accepted'
      AND NOT EXISTS (SELECT 1 FROM curriculum_repository_links l WHERE l.data_object_id = o.id);
  SELECT count(*) INTO sbx FROM project_repository_links x JOIN projects p ON p.id = x.project_id WHERE p.slug = 'evomentor-thuringia-sandbox';
  SELECT EXISTS (SELECT 1 FROM curriculum_repository_records WHERE source_record_id = 'DELP-MANDATE-thueringen-doppelklassenstufe-lehrkraft-freiraum' AND content ? 'gradeBands') INTO bands;
  IF untagged56 <> 0 OR unlinked56 <> 0 OR sbx < 1 OR NOT bands THEN
    RAISE EXCEPTION 'migration 215: untagged 5/6 goals %, unlinked 5/6 goals %, sandbox project links %, gradeBands set %', untagged56, unlinked56, sbx, bands;
  END IF;
END $$;
